with scored as (select *, sum(discount_pct) over w_part as cumulative_discount_pct, lag(discount_pct, 2) over (partition by channel, promo_code order by discount_pct, id) as prev_discount_pct, avg(discount_pct) over w_hist as channel_avg_discount_pct from promotions window w_part as (partition by promo_code order by discount_pct, id rows between unbounded preceding and current row), w_hist as (partition by channel)) select promo_code, round(avg(discount_pct), 2) as avg_discount_pct, sort_array(collect_set(channel)) as channel_list, sum(case when promo_code = 'VIP' then cumulative_discount_pct else 0 end) as vip_cumulative_discount_pct, count(*) filter (where promo_code = 'SPRING10') as spring10_rows, sort_array(collect_set(promo_code)) as promo_code_list from scored group by promo_code having avg_discount_pct >= 0 order by spring10_rows desc nulls first
